import json
import os
import base64
from pathlib import Path
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey

def test_cross_language_mandate_signature():
    # Load vector generated by Go gateway
    vector_path = Path(__file__).resolve().parent.parent.parent / "contracts" / "test_vectors" / "mandate_signing_vector.json"
    if not vector_path.exists():
        # Fallback to gateway/contracts if run in different environment
        vector_path = Path(__file__).resolve().parent.parent.parent / "gateway" / "contracts" / "test_vectors" / "mandate_signing_vector.json"

    assert vector_path.exists(), f"vector file missing at {vector_path}"

    with open(vector_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    pub_bytes = base64.b64decode(data["public_key_base64"])
    sig_bytes = base64.b64decode(data["signature_base64"])
    canonical_bytes = data["canonical_json"].encode("utf-8")

    # Verify using Python's standard cryptography library
    public_key = Ed25519PublicKey.from_public_bytes(pub_bytes)
    
    # Should not raise cryptography.exceptions.InvalidSignature
    public_key.verify(sig_bytes, canonical_bytes)
